    param x: f32;
    position: vec3(x, 0.0, 0.0);
    mesh: Box { size: vec3(0.8, 0.8, 0.5) };
    material: Unlit { color: #38bdf8 };
}

scene Demo {
    clear_color: #202020;

    state pip_count: i32 = 0;
    state pip_refs: array<entity_ref, 5> = [null, null, null, null, null];

    camera Main {
        position: vec3(0.0, 0.0, 10.0);
        target: vec3(0.0, 0.0, 0.0);
        projection: Orthographic { height: 12.8 };
    }

    entity Rail {
        position: vec3(0.0, -1.5, 0.0);
        mesh: Box { size: vec3(12.0, 0.2, 0.2) };
        material: Unlit { color: #404040 };
    }

    on key_down(key: Key) {
        if key == Key::Space {
            if pip_count < 5 {
                let x_pos: f32 = -4.0 + 2.0 * (pip_count as f32);
                let new_pip: entity_ref = spawn Pip { x: x_pos; };
                pip_refs[pip_count] = new_pip;
                pip_count = pip_count + 1;
            }
        }
        if key == Key::Backspace {
            if pip_count > 0 {
                pip_count = pip_count - 1;
                let pip_to_remove: entity_ref = pip_refs[pip_count];
                destroy(pip_to_remove);
                pip_refs[pip_count] = null;
            }
        }
        if key == Key::Enter {
            for i in 0 .. pip_count {
                destroy(pip_refs[i]);
                pip_refs[i] = null;
            }
            pip_count = 0;
        }
    }
}
>>>REPLACE
>>>END

